<script lang="ts">
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {copy,noticeText,failureCode} from '$lib/shared/presentation/copy';
 const {locale,change:changeLanguage}=useLocale();
 import LibrarySyncStatus from './LibrarySyncStatus.svelte';
 import type {LibrarySync} from '../application/library-sync';
 import {onMount} from 'svelte';
 import type {TitleDetail} from '../../catalog/application/catalog';
 import type {ReadingGateway,Selection} from '../application/progress';
 let {title,readingGateway,librarySync,onstatuschange}:{title:TitleDetail;readingGateway:ReadingGateway;librarySync?:LibrarySync;onstatuschange?:(status:string|null)=>void}=$props();
 let account=$state<string|null>(null),selection=$state<Selection>({titleId:'',status:'reading',favorite:false,preferredTeamId:'',notify:true}),saved=$state(false),busy=$state(true),message=$state(''),resume=$state('');
 onMount(()=>{void(async()=>{try{account=await readingGateway.account();if(account){const item=await readingGateway.selection(account,title.id);if(item&&!item.removed){selection={...item,removed:false};saved=true;resume=item.progress.releaseId;}}selection.titleId=title.id;}catch{message="library_failed";}finally{busy=false;}})();});
 $effect(()=>{onstatuschange?.(saved?selection.status:null);});
 async function save(next:Selection=selection){if(!account)return;busy=true;message='';try{await readingGateway.save(account,{...next,removed:false});selection={...next,removed:false};saved=true;message=(await librarySync?.state(account,title.id))?.pending?'':"library_saved";const fresh=await readingGateway.selection(account,title.id);if(fresh)selection={...fresh,removed:false};}catch(failure){message=failureCode(failure);}finally{busy=false;}}
 function chooseStatus(status:string){const team=selection.preferredTeamId;void save({...selection,titleId:title.id,status,preferredTeamId:team});}
</script>
<section class="selection"><h2>{copy($locale,"Менің кітапханам")}</h2>{#if busy}<p role="status">{copy($locale,"Жүктелуде…")}</p>{:else if account}<p class="muted">{text($locale,'Тізім түрін таңда — бірден сақталады.','Выбери список — он сохранится сразу.')}</p><div class="status-choices" role="group" aria-label={copy($locale,"Оқу мәртебесі")}>{#each [{value:'reading',label:copy($locale,"Оқып жүрмін")},{value:'planned',label:copy($locale,"Жоспарда")},{value:'completed',label:copy($locale,"Оқып болдым")},{value:'paused',label:copy($locale,"Үзілісте")},{value:'dropped',label:copy($locale,"Тоқтаттым")}] as option}<button type="button" class="button subtle" aria-pressed={saved&&selection.status===option.value} onclick={()=>chooseStatus(option.value)} disabled={busy}>{option.label}</button>{/each}</div><details class="preferences"><summary>{text($locale,'Қосымша баптаулар','Дополнительные настройки')}</summary><form onsubmit={event=>{event.preventDefault();void save();}}><label>{copy($locale,"Қалаған аударма тобы")}<select bind:value={selection.preferredTeamId}><option value="">{copy($locale,"Таңдалмаған")}</option>{#each title.projects as project}<option value={project.teamId}>{project.teamName}</option>{/each}</select></label><label class="check"><input type="checkbox" bind:checked={selection.favorite}/>{copy($locale,"Таңдаулы")}</label><label class="check"><input type="checkbox" bind:checked={selection.notify}/>{copy($locale,"Жаңа тараулар туралы хабарлау")}</label><button class="button subtle" disabled={busy}>{copy($locale,"Сақтау")}</button></form></details>{#if resume}<a class="button subtle" href={`/read/${resume}`}>{copy($locale,"Оқуды жалғастыру")}</a>{/if}{:else}<p class="muted">{copy($locale,"Оқу орны қонақ ретінде де құрылғыда сақталады. Кітапхана үшін ")}<a class="auth-link" href={'/login?returnTo='+encodeURIComponent('/titles/'+title.slug)}>{copy($locale,"кіріңіз")}</a>.</p>{/if}{#if message}<p role="status">{noticeText($locale,message)}</p>{/if}{#if account&&librarySync}<LibrarySyncStatus sync={librarySync} {account} onresolved={()=>{if(account)void readingGateway.selection(account,title.id).then(item=>{if(item&&!item.removed){selection={...item,removed:false};saved=true;resume=item.progress.releaseId;}}).catch(failure=>message=failureCode(failure));}}/>{/if}</section>
<style>.selection{margin-top:0;padding:8px 0}.selection h2{font-size:16px;margin-bottom:12px}form{display:flex;flex-wrap:wrap;align-items:end;gap:12px}label{display:grid;gap:8px;font-size:13px;flex:1 1 200px}.check{display:flex;align-items:center;min-height:44px;gap:8px}.check input{width:20px;height:20px;min-height:20px}.status-choices{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;margin:14px 0}.status-choices button{min-height:44px;white-space:normal}.status-choices button[aria-pressed="true"]{border-color:var(--accent);color:var(--accent);font-weight:700}.preferences{border-top:1px solid var(--line);margin:16px 0;padding-top:8px}.preferences summary{min-height:44px;cursor:pointer;color:var(--muted)}.selection .muted{font-size:13px;line-height:1.5}
</style>
